def fill(template, record):
    out = dict(record)
    for key, value in template.items():
        if key not in out:
            out[key] = value
        elif isinstance(value, dict) and isinstance(out[key], dict):
            out[key] = fill(value, out[key])
    return out

def solve(p):
    return fill(p[0], p[1])

